function middleCar(next, head) {
  const order = [];
  for (let node = head; node !== -1; node = next[node]) order.push(node);
  return order[Math.floor(order.length / 2)];
}

function middleCar(next, head) {
  let slow = head, fast = head;
  while (fast !== -1 && next[fast] !== -1) {
    slow = next[slow];
    fast = next[next[fast]];
  }
  return slow;
}
